# Run from the repo root:  python3 apply_all.py
# Applies, in order and skipping any that are already in: (1) level no longer changes stats/damage, (2) EV-byte guard + enemy seeding.
import base64, os, subprocess, sys
if not os.path.isdir('src') or not os.path.isdir('include'): sys.exit("STOP: run from the repo root")
hdr = open('include/attribute_points.h', encoding='utf-8').read() if os.path.exists('include/attribute_points.h') else ''
if not hdr: sys.exit("STOP: include/attribute_points.h missing - the base attribute files are not in this copy")
STEPS = [("level-free stats and damage", "ATTR_REF_LEVEL", ""), ("EV guard + enemy seeding", "gAttrWriteAllowed", "")]
for name, marker, blob in STEPS:
    hdr = open('include/attribute_points.h', encoding='utf-8').read()
    print("---", name)
    if marker in hdr: print("already in, skipping"); continue
    path = "/tmp/_step.py"; open(path, "wb").write(base64.b64decode(blob))
    if subprocess.run([sys.executable, path]).returncode: sys.exit("STOPPED at: " + name + " (nothing from this step was changed)")
print("\nALL DONE. Now run:  make -j$(nproc)")
